  const list = S.sessions.filter((s) => (S.sessFilter === 'all' || s.tool === S.sessFilter) && (!q || (s.title + s.path + s.model).toLowerCase().includes(q)));
  const rows = list.map((s) => `<div class="sess ${s.archived ? 'archived' : ''}" onclick="A.openSession(${s.id})">${brand(s.tool, 'mini')}<div><strong>${esc(s.title)}${s.archived ? ' <span class="pill" style="height:18px;margin-left:6px">已归档</span>' : ''}</strong><span class="p">${esc(s.path)}</span></div><span class="n">${modelIcon(s.model)}${s.model}</span><span class="n">${s.msgs} 条</span><span class="n">${s.when}</span></div>`).join('');
  return `<section class="page">${pageHead('记录', '查看以前的对话。从本机会话文件只读加载，不会改动原文件。', `<button class="btn btn-ghost icon" title="刷新会话" onclick="A.toast('会话列表已刷新')">${ic('refresh')}</button>`)}
    <div class="toolbar"><span class="segment"><button class="${S.sessFilter === 'all' ? 'on' : ''}" onclick="S.sessFilter='all';rerenderMain()">全部</button>${['claude', 'codex', 'gemini', 'grok'].map((id) => `<button class="${S.sessFilter === id ? 'on' : ''}" onclick="S.sessFilter='${id}';rerenderMain()">${brand(id, 'xs')}${TOOLS[id].name}</button>`).join('')}</span>
      <label class="search">${ic('search')}<input class="input" placeholder="搜索标题、目录、模型或会话 ID" value="${esc(S.q.sessions || '')}" oninput="A.search('sessions',this.value)"></label><span class="count" id="count-sessions">${list.length} 个会话</span></div>
    <div class="card list" id="list-sessions">${rows || emptyHtml('clock', q ? '没有找到对话' : '还没有对话记录', q ? '换个词再搜。' : '打开工具聊过之后，这里会出现记录。')}</div>
    <div style="display:flex;justify-content:flex-end;gap:6px;margin-top:10px;color:var(--text-3);font-size:12px;align-items:center">第 1 / 1 页<button class="btn btn-ghost icon xs" disabled>${ic('left')}</button><button class="btn btn-ghost icon xs" disabled>${ic('right')}</button></div></section>`;
