  toolMenu(e, id) { const st = toolState(id); A.menu(e, [...(st === 'update' ? [{ label: `更新到 ${TOOLS[id].latest}`, icon: 'dl', run: () => A.install(id) }] : []), { label: '配置', icon: 'gear', run: () => A.dialog('config', { tool: id }) }, { label: '查看 Key 状态', icon: 'key', run: () => A.toast(S.tools[id].configured ? `已写入 · 指向 xm.solov.cc · ${S.keys.find((k) => k.id === S.tools[id].key)?.masked || ''}` : '还没写入 Key', S.tools[id].configured ? undefined : 'warn') }, { label: '备份配置', icon: 'archive', run: () => { S.backupTool = id === 'codexDesktop' ? 'codex' : id; A.go('backups'); } }, 'hr', { label: '卸载', icon: 'trash', danger: true, run: () => A.uninstall(id) }]); },
