  /* 备份 / 检查 */
  backupNow() { S.installing.backup = 0; render(); later(() => { delete S.installing.backup; S.backups.unshift({ id: Date.now(), tool: S.backupTool, when: '刚刚', kind: '手工备份', files: { claude: ['~/.claude/settings.json', '~/.claude.json'], codex: ['~/.codex/config.toml', '~/.codex/auth.json'], gemini: ['~/.gemini/settings.json'] }[S.backupTool], size: '3.2 KB' }); render(); A.toast(`${TOOLS[S.backupTool].name} 配置已备份`); log('info', '手工备份完成', TOOLS[S.backupTool].name); }, 1200); },
