  backupDelete(id) { A.confirm({ title: '删除这份备份？', body: '删除后不能找回。', ok: '删除', danger: true, run: () => { S.backups = S.backups.filter((x) => x.id !== id); A.toast('备份已删除'); } }); },
  healthRun() { S.health = { status: 'running', items: HEALTH_ITEMS.map((x) => ({ k: x.k, label: x.label, st: 'wait', fix: x.fix })) }; render(); let i = 0;
    const step = () => { if (i > 0) { const def = HEALTH_ITEMS[i - 1], it = S.health.items[i - 1]; const ok = def.ok(); if (ok) { it.st = 'ok'; it.detail = ok; } else if (def.warn) { it.st = 'warn'; it.detail = def.warn(); } else { it.st = 'bad'; it.detail = def.fail; } }
      if (i < HEALTH_ITEMS.length) { S.health.items[i].st = 'run'; i++; render(); later(step, 450); } else { S.health.status = 'done'; S.health.finishedAt = new Date().toTimeString().slice(0, 5); render(); const bad = S.health.items.filter((x) => x.st === 'bad').length; A.toast(bad ? `检查完成，${bad} 项需要处理` : '检查完成，环境正常', bad ? 'warn' : undefined); log('info', '环境检查完成', `${S.health.items.filter((x) => x.st === 'ok').length}/${HEALTH_ITEMS.length} 正常`); } }; later(step, 300); },
