  kfPop(e) { e.stopPropagation(); if (S.kfPop) { S.kfPop = null; render(); return; } const r = e.currentTarget.getBoundingClientRect(), w = $('#win').getBoundingClientRect(); S.kfPop = { x: Math.max(8, r.right - w.left - 264), y: r.bottom - w.top + 8 }; S.menu = null; render(); },
