  sendCode() { const f = S.form, owner = topDialog(); if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(f.email || '')) { f.err = '请先填一个正确的邮箱'; render(); return; } f.err = ''; f.sent = true; f.cd = 60; render(); A.toast(`验证码已发送到 ${f.email}`); const tick = () => { if (!S.dialogs.includes(owner) || f.cd == null) return; f.cd -= 1; if (f.cd <= 0) delete f.cd; const b = document.querySelector(`[data-dialog-id="${owner.id}"] .field-row .btn`); if (b) { b.disabled = Boolean(f.cd); b.textContent = f.cd ? f.cd + ' 秒后重发' : '重新发送'; } if (f.cd) later(tick, 1000); }; later(tick, 1000); },
  sendReset() { const f = S.form, owner = topDialog(); if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(f.email || '')) { A.toast('请先填一个正确的邮箱', 'warn'); return; } f.step = 2; f.cd = 60; render(); A.toast('重置邮件已发送（若邮箱已注册）'); later(() => { if (S.dialogs.includes(owner)) { delete f.cd; render(); } }, 60000); },
