  accPop(e) { e.stopPropagation(); if (S.accPop) { S.accPop = null; render(); return; } const r = e.currentTarget.closest('.account').getBoundingClientRect(), w = $('#win').getBoundingClientRect(); S.accPop = { x: r.right - w.left + 8, y: Math.max(8, r.top - w.top - 120) }; render(); },
