  fixKey(id) { A.toast('正在用新 Key 重新写入 Claude Code 配置…'); later(() => { S.sim = ''; S.keys.filter((k) => k.id === 'k1').forEach((k) => { k.status = 'revoked'; }); S.keys.push({ id: 'k1b', name: 'Claude Code · 本机（新）', group: 'Claude 专线', masked: 'sk-xm-****-B3c9', full: 'sk-xm-1a2b3c4d5e6f7a8b9c0d1e2fB3c9', status: 'active', created: '2026-09-06', used: '刚刚', show: false }); S.tools.claude.key = 'k1b'; render(); A.toast('已修复：新 Key 已写入，旧 Key 已撤销'); }, 1200); },
