  coachEnd() { S.coach = null; S.coachDone = true; render(); A.toast('引导结束，随时可以在设置里再看一遍'); },
  osNotify(title, body) { const el = document.createElement('div'); el.className = 'osnotify'; el.innerHTML = `${logo('micro', 36)}<div><div class="app">星芒AI管理工具 · 现在</div><strong>${esc(title)}</strong><p>${esc(body)}</p></div>`; document.body.appendChild(el); el.onclick = () => el.remove(); setTimeout(() => el.remove(), 4500); },
